window.OSHA_QUESTIONS_SET4 = [
  { id: "dm-01", category: "demolition", topic: "Subpart T", q: "Construction demolition is covered by:", choices: ["1926 Subpart T", "1910.146 only", "1926 Subpart M only", "The general duty clause exclusively"], a: 0, why: "1926.850–860: engineering survey, utilities, and sequential demolition." },
  { id: "dm-02", category: "demolition", topic: "Engineering survey", q: "Before demolition, a competent person must make a written:", choices: ["Engineering survey of the structure’s condition and the possibility of unplanned collapse", "Marketing brochure", "Only a photo", "Verbal guess"], a: 0, why: "1926.850(a): written survey. Check adjacent structures too." },
  { id: "dm-03", category: "demolition", topic: "Utilities demo", q: "Electric, gas, water, steam, and other service lines must be:", choices: ["Shut off, capped, or otherwise controlled outside the building before demo, except as needed and protected", "Left live for lighting", "Cut at random", "Ignored if the building is empty"], a: 0, why: "1926.850(c): locate and protect remaining lines. Call 811 for buried utilities." },
  { id: "dm-04", category: "demolition", topic: "Hazardous materials", q: "Before demo, employers must determine whether:", choices: ["Asbestos, lead, PCBs, or other hazardous materials are present and handle them under the applicable standards", "The building is historic only", "Paint color matches", "Only rats are present"], a: 0, why: "NESHAP asbestos, 1926.62 lead, and 1910.120 if it becomes a waste site. Survey first." },
  { id: "dm-05", category: "demolition", topic: "Chutes", q: "Debris chutes generally need:", choices: ["Enclosed or guarded openings; a substantial gate at each chute opening when the chute is not attended", "Open hoppers at every floor with no protection", "Workers standing under the discharge", "Cardboard lining only"], a: 0, why: "1926.852: chutes. Keep people out of the drop zone." },
  { id: "dm-06", category: "demolition", topic: "Floor openings demo", q: "Holes cut for debris drop must be:", choices: ["Barricaded and not used as walkways; covers when required", "Left unmarked as a shortcut", "Covered with visqueen only", "Used as stair substitutions"], a: 0, why: "1926.850(k) and Subpart M: falling and falling-object hazards." },
  { id: "dm-07", category: "demolition", topic: "Walls", q: "Walls shall not be left standing unless:", choices: ["They are stable against wind and other forces, or are shored", "They look straight", "The inspector has not arrived", "They have wallpaper"], a: 0, why: "1926.854–855: masonry walls, floor arches. Sequential demo so you do not create a collapse." },
  { id: "dm-08", category: "demolition", topic: "Stairs demo", q: "During demo, assigned stairs, passageways, and ladders must be:", choices: ["Maintained and adequately lighted; other access closed", "Removed first always", "Used to store debris", "Unlit to save power"], a: 0, why: "1926.850(m)–(n): keep a safe path for workers still in the building." },
  { id: "dm-09", category: "demolition", topic: "Mechanical demo", q: "When using a wrecking ball or high-reach excavator:", choices: ["Keep workers out of the danger area; the operator must have a clear view or a signal person", "Stand next to the wall being pulled", "Use a tag line on the ball with people underneath", "Work at night without lights"], a: 0, why: "1926.859: mechanical demolition. Unexpected collapses travel farther than you think." },
  { id: "dm-10", category: "demolition", topic: "Steel demo", q: "Steel structures being dismantled:", choices: ["Need a plan so members are not dropped; flooring should remain in place except for openings needed", "Can be torch-cut so everything falls at once without a plan", "Need no fall protection", "Are exempt from crane rules"], a: 0, why: "1926.858: removal of steel. Fall protection still applies. Cranes still follow Subpart CC." },
  { id: "dm-11", category: "demolition", topic: "Fire demo", q: "A fire from demo (torch cutting, hot work) requires:", choices: ["Fire prevention like any hot work — extinguishers, watch, and no cutting in explosive atmospheres", "No precautions because the building is coming down", "Gasoline to speed the cut", "Leaving oxygen cylinders in the rubble"], a: 0, why: "1926.850 and Subpart J still apply. Tanks and residual chemicals explode." },
  { id: "dm-12", category: "demolition", topic: "Dust", q: "Demo dust may contain:", choices: ["Silica, asbestos, lead, and mold — use water, PPE, and isolation", "Only nuisance dirt that is never regulated", "Pure oxygen", "Helium"], a: 0, why: "Wet methods, negative air when required, and worker protection. Neighbors may have EPA/NESHAP duties too." },

  { id: "rk-01", category: "recordkeeping", topic: "Who keeps logs", q: "OSHA injury/illness recordkeeping (Part 1904) generally applies to:", choices: ["Employers with 11 or more employees, with some low-hazard industry exemptions", "Every employer including the self-employed with no workers", "Only construction GCs", "Only manufacturers with 1,000 employees"], a: 0, why: "1904.1–2: size and industry exemptions. All employers must report severe injuries even if they do not keep 300 logs." },
  { id: "rk-02", category: "recordkeeping", topic: "Work-related", q: "An injury is work-related if:", choices: ["An event or exposure in the work environment either caused or contributed to the condition, with listed exceptions", "It happens anywhere the worker goes 24/7", "It is only a cold caught from a coworker’s child", "The worker was at home teleworking on a personal errand"], a: 0, why: "1904.5: geographic presumption with exceptions (eating, personal tasks, common colds, etc.)." },
  { id: "rk-03", category: "recordkeeping", topic: "Recordable", q: "A work-related injury is recordable if it results in:", choices: ["Death, days away, restricted work, transfer, medical treatment beyond first aid, loss of consciousness, or a significant injury diagnosed by a PLHCP", "Only death", "A bandage", "A tetanus shot alone in some first-aid cases"], a: 0, why: "1904.7: the recording criteria. First aid vs medical treatment is defined in 1904.7(b)(5)." },
  { id: "rk-04", category: "recordkeeping", topic: "First aid vs treatment", q: "Which is generally first aid (not recordable by itself)?", choices: ["Using non-prescription medication at non-prescription strength, bandages, and tetanus immunizations", "Prescription medication", "Stitches", "Casts"], a: 0, why: "1904.7(b)(5)(ii) lists first-aid treatments. Prescription meds, sutures, and devices that immobilize are typically medical treatment." },
  { id: "rk-05", category: "recordkeeping", topic: "Needlestick", q: "Needlesticks and cuts from sharps contaminated with another person’s blood:", choices: ["Are recordable on the OSHA log (and on a sharps log for BBP) as specified", "Are never recordable", "Are only HIPAA issues", "Go only on Form 301 if nobody knows"], a: 0, why: "1904.8: needlesticks. Privacy concern cases have special recording rules." },
  { id: "rk-06", category: "recordkeeping", topic: "Hearing STS", q: "A work-related Standard Threshold Shift may be recordable when:", choices: ["The employee’s total hearing level is 25 dB or more above audiometric zero in the same frequencies, among other 1904.10 rules", "Any ringing in the ears", "A one-time loud noise with no audiogram change", "Only if the worker is angry"], a: 0, why: "1904.10: hearing loss recording. Age adjustment and retesting rules apply." },
  { id: "rk-07", category: "recordkeeping", topic: "TB", q: "A work-related tuberculosis infection (positive skin test after occupational exposure) is:", choices: ["Recordable under 1904.11", "Never recordable", "Only a CDC issue", "First aid"], a: 0, why: "1904.11: TB. Medical removal and treatment affect days away/restricted." },
  { id: "rk-08", category: "recordkeeping", topic: "Privacy cases", q: "For privacy concern cases (certain intimate injuries, mental illness, needlesticks, etc.) the employer:", choices: ["May omit the name from the 300 log and keep a confidential list", "Must post the name on the bulletin board", "Cannot record the case", "Must call the newspaper"], a: 0, why: "1904.29(b)(6)–(9): privacy cases. Do not enter “privacy case” details that identify the person in the posted 300A." },
  { id: "rk-09", category: "recordkeeping", topic: "301", q: "Form 301 (or equivalent) must be completed within:", choices: ["7 calendar days of receiving information that a recordable case occurred", "8 hours", "1 year", "The day of the 300A posting only"], a: 0, why: "1904.29(b)(3): 7 days for 300 and 301. Fatality/severe reporting to OSHA is still 8/24 hours." },
  { id: "rk-10", category: "recordkeeping", topic: "Retention", q: "The 300, 300A, and 301 forms must be retained:", choices: ["5 years following the year to which they relate", "30 days", "1 year", "Forever in every case"], a: 0, why: "1904.33: 5 years. Update the 300 during that period if the case classification changes." },
  { id: "rk-11", category: "recordkeeping", topic: "Employee access", q: "Workers and their representatives have a right to:", choices: ["Access the 300 log (with privacy protections) in a reasonable time", "The employer’s tax records", "OSHA’s unredacted investigative file always", "No injury data"], a: 0, why: "1904.35 / 1904.40: access. Provide by the end of the next business day for the 300 log in many cases." },
  { id: "rk-12", category: "recordkeeping", topic: "Electronic submit", q: "Certain establishments must electronically submit injury data to OSHA:", choices: ["Through OSHA’s Injury Tracking Application as required by size/NAICS (300A and in some cases 300/301 data)", "By fax to the local fire department only", "Never if they have a 300 log", "Only if they had a fatality"], a: 0, why: "1904.41: electronic submission. Thresholds have changed — check current OSHA ITA rules." },
  { id: "rk-13", category: "recordkeeping", topic: "New vs old", q: "A case is new if:", choices: ["The employee has not previously experienced the same work-related illness from the same type of exposure, or a previous injury has healed then been re-injured, as specified", "Every ache is a new case always", "Nothing is ever new", "Only lawsuits create cases"], a: 0, why: "1904.6: new vs recurring. Chronic illnesses can be complicated — follow the decision tree." },
  { id: "rk-14", category: "recordkeeping", topic: "Travel status", q: "An injury in a hotel on a business trip is:", choices: ["Generally work-related if the employee is there in the interest of the employer, with exceptions for personal detours", "Never work-related", "Always recordable even if first aid", "Covered only by workers’ comp, never OSHA"], a: 0, why: "1904.5(b)(6): travel. A side trip to a museum on personal time can be an exception." },
  { id: "rk-15", category: "recordkeeping", topic: "Work from home", q: "Injuries while working from home are work-related if:", choices: ["They occur while the employee is performing work for pay or compensation in the home work area, and are directly related to the performance of work rather than the home environment generally", "Any home injury counts", "Never", "Only if a supervisor is watching"], a: 0, why: "1904.5(b)(7): telework. Tripping over the family dog while not working is not work-related." },
  { id: "rk-16", category: "recordkeeping", topic: "Temp workers", q: "For temporary workers from a staffing agency, the 300 log is generally kept by:", choices: ["The host employer who supervises the worker day to day", "Nobody", "OSHA", "The worker"], a: 0, why: "1904.31: the employer who supervises records. The staffing agency may still have duties. Coordinate so cases are not double-counted incorrectly — typically the supervising employer records." },
  { id: "rk-17", category: "recordkeeping", topic: "Contractor", q: "On a construction site, a subcontractor’s injured employee is logged by:", choices: ["The employer of that worker (the sub), not automatically the GC’s 300 log", "Always the GC only", "Always the owner", "Nobody if they have a 1099"], a: 0, why: "Each employer logs their own employees. Misclassified employees can still be employees under the law." },
  { id: "rk-18", category: "recordkeeping", topic: "300A certify", q: "The 300A must be certified by:", choices: ["A company executive (as defined in 1904.32)", "Any intern", "The injured worker", "An OSHA consultant"], a: 0, why: "1904.32(b)(3): highest ranking site official, or a corporate officer, etc. Review the log before certifying." },
  { id: "rk-19", category: "recordkeeping", topic: "DART", q: "DART rate is based on:", choices: ["Days away, restricted, or transfer cases", "Only first aid", "Near misses", "Training hours"], a: 0, why: "Used in OSHA and contractor prequalification. Recordable rate uses all recordables." },
  { id: "rk-20", category: "recordkeeping", topic: "Anti-retaliation", q: "Employers must not:", choices: ["Retaliate against workers for reporting injuries (1904.35 / 11(c))", "Encourage reporting", "Provide first aid", "Post the 300A"], a: 0, why: "Safety incentive programs that punish reporting are a problem. Reasonable drug testing policies have limits after injury reports." },

  { id: "fa-01", category: "firstaid", topic: "1910.151", q: "If a workplace is not near a clinic or hospital, the employer must have:", choices: ["Personnel trained to render first aid, and first-aid supplies", "No medical plan", "Only a poster", "911 as the sole plan with no supplies"], a: 0, why: "1910.151(b): trained first-aiders when infirmaries/clinics/hospitals are not in near proximity. Construction 1926.50 is similar." },
  { id: "fa-02", category: "firstaid", topic: "Eyewash", q: "Where a person’s eyes or body may be exposed to injurious corrosive materials, the employer must provide:", choices: ["Suitable facilities for quick drenching or flushing within the work area for immediate emergency use", "A restroom down the hall only", "Bottled water in a truck 10 minutes away", "A garden hose with no pressure control as the only option always"], a: 0, why: "1910.151(c): eyewash/shower. ANSI Z358.1 is the consensus (about 10 seconds / 55 feet is a common benchmark) though OSHA’s text says “within the work area.”" },
  { id: "fa-03", category: "firstaid", topic: "Construction medical", q: "1926.50 requires:", choices: ["First-aid supplies, trained person in the absence of an infirmary, and prompt medical attention", "A full hospital on every job", "No water", "Only a first-aid app"], a: 0, why: "Also telephone numbers of physicians, hospitals, and ambulances posted. Drinking water required under 1926.51." },
  { id: "fa-04", category: "firstaid", topic: "Blood first aid", q: "First-aid responders with occupational exposure to blood need:", choices: ["BBP training, PPE, and the hepatitis B vaccine offer", "No gloves", "To recap needles", "To delay care until EMS only, always"], a: 0, why: "Treat the patient, protect yourself. Gloves, eyewear, and a CPR barrier as needed." },
  { id: "fa-05", category: "firstaid", topic: "Shock electric", q: "After an electrical shock, once the scene is safe:", choices: ["Call EMS; the person may have heart-rhythm problems even if they “feel fine”", "Have them go back to work immediately always", "Pour water on burns from live equipment while it is still energized", "Move a possible spinal injury casually"], a: 0, why: "Electrical burns can be internal. High-voltage victims need trauma care. Do not become a victim." },
  { id: "fa-06", category: "firstaid", topic: "Heat first aid", q: "Heat exhaustion (heavy sweating, weakness, nausea) first response is:", choices: ["Move to shade, cool, hydrate if conscious; escalate if it becomes heat stroke", "More strenuous work to “sweat it out”", "Salt tablets without water", "Leave them in the sun"], a: 0, why: "Know the difference from heat stroke (altered mental status). When in doubt, cool and call 911." },
  { id: "fa-07", category: "firstaid", topic: "Bleeding", q: "Severe bleeding control:", choices: ["Direct pressure with barrier protection; tourniquet if trained and life-threatening limb bleed", "A loose tissue on top", "Aspirin only", "Wait and see"], a: 0, why: "Stop-the-bleed principles. Protect yourself from BBP. EMS as soon as possible." },
  { id: "fa-08", category: "firstaid", topic: "Chem splash", q: "Chemical splash to the eyes:", choices: ["Flush immediately at the eyewash for the SDS-specified time (often 15 minutes) while holding lids open, then medical care", "Neutralize acids with a base in the eye", "Rub the eye", "Wait until the shift ends"], a: 0, why: "Seconds matter. Remove contacts. Take the SDS to the ER." },
  { id: "fa-09", category: "firstaid", topic: "Kit", q: "First-aid kits should be:", choices: ["Accessible, stocked, and appropriate to the workplace hazards", "Locked in the owner’s truck off-site", "Expired as a cost-saving measure", "Used as a tool kit"], a: 0, why: "ANSI/ISEA Z308.1 is a common kit standard. Inspect regularly. 1926.50 Appendix A has a reference list." },
  { id: "fa-10", category: "firstaid", topic: "AED", q: "AEDs in the workplace:", choices: ["Are not specifically mandated by a single OSHA AED standard but are a recognized way to improve survival; train users and maintain the device", "Are banned by OSHA", "Replace first-aid training", "Work without pads"], a: 0, why: "Good practice for large sites and high-risk work. Include AEDs in the EAP if you have them." },

  { id: "ps-01", category: "psm", topic: "Standard", q: "Process Safety Management of highly hazardous chemicals is:", choices: ["1910.119", "1926.501", "1910.178", "1904.39"], a: 0, why: "PSM applies to processes with listed chemicals at or above threshold quantities, and to flammable liquids/gases of 10,000 pounds or more with exceptions." },
  { id: "ps-02", category: "psm", topic: "Threshold", q: "PSM covers flammable liquids or gases in a process at or above:", choices: ["10,000 pounds, with exceptions such as hydrocarbon fuels used solely for workplace consumption of those fuels", "10 pounds always", "Any amount of gasoline in a truck", "1 million pounds only"], a: 0, why: "1910.119(a). Appendix A lists toxic chemicals and TQs (e.g., anhydrous ammonia 10,000 lb, chlorine 1,500 lb)." },
  { id: "ps-03", category: "psm", topic: "PSI", q: "Process Safety Information includes:", choices: ["Hazards of the chemicals, technology of the process, and equipment (including materials of construction and P&IDs)", "Only the company logo", "Payroll", "OSHA 10 cards"], a: 0, why: "1910.119(d): PSI must be complete before PHA. Codes and standards used for design are included." },
  { id: "ps-04", category: "psm", topic: "PHA", q: "A Process Hazard Analysis must be:", choices: ["Performed by a team including at least one person with experience in the process, using a recognized method (What-If, HAZOP, etc.), and updated at least every 5 years", "A one-person memo", "Optional", "Done only after an explosion"], a: 0, why: "1910.119(e): system to address findings in a timely manner. Revalidate every 5 years." },
  { id: "ps-05", category: "psm", topic: "Op procedures", q: "Operating procedures must cover:", choices: ["Initial startup, normal, temporary, emergency shutdown, emergency operations, normal shutdown, and startup after a turnaround, plus safety systems and their functions", "Only the night shift", "How to skip interlocks", "Break times only"], a: 0, why: "1910.119(f): procedures must be current, clear, and certified annually as current." },
  { id: "ps-06", category: "psm", topic: "MOC", q: "Management of Change is required for:", choices: ["Changes to process chemicals, technology, equipment, and procedures (not “replacement in kind”)", "Changing a light bulb that is truly replacement in kind", "The cafeteria menu", "Paint color in the office"], a: 0, why: "1910.119(l): MOC before the change. Inform and train affected employees. Update PSI and procedures." },
  { id: "ps-07", category: "psm", topic: "MI", q: "Mechanical Integrity applies to:", choices: ["Pressure vessels, storage tanks, piping, relief systems, emergency shutdown, controls, and pumps handling highly hazardous chemicals", "Office chairs", "The parking lot", "Hand tools only"], a: 0, why: "1910.119(j): written procedures, training, inspection/testing per RAGAGEP, and correction of deficiencies." },
  { id: "ps-08", category: "psm", topic: "HOT work PSM", q: "Hot work in a PSM process area requires:", choices: ["A hot-work permit (1910.119(k) and 1910.252)", "No permit if you work for the plant", "Welding on live lines always", "Only a hard hat"], a: 0, why: "Permits document fire prevention and isolation. Many incidents start as “routine” welding." },
  { id: "ps-09", category: "psm", topic: "Incident investigation", q: "PSM incident investigations must start:", choices: ["As promptly as possible, but not later than 48 hours after the incident", "Within 1 year", "Never if nobody died", "Only if OSHA is already on site"], a: 0, why: "1910.119(m): report, recommendations, and sharing with contractors and employees whose work is relevant." },
  { id: "ps-10", category: "psm", topic: "Contractors PSM", q: "Host employers must:", choices: ["Inform contract employers of known fire, explosion, or toxic hazards related to the contractor’s work and the process, and of the emergency plan", "Hide process hazards from contractors", "Assume contractors know everything", "Skip orientation"], a: 0, why: "1910.119(h): evaluate contractor safety programs, periodic performance, and a contract-employee injury/illness log related to the contractor’s work in the process areas." },
  { id: "ps-11", category: "psm", topic: "CSTOP", q: "Pre-startup safety review is required for:", choices: ["New facilities and modified facilities when the modification is significant enough to require a change in PSI", "Every coffee maker", "Only software updates in HR", "Parking lot resealing"], a: 0, why: "1910.119(i): PSSR confirms construction is in accordance with design, procedures are in place, and training is done." },
  { id: "ps-12", category: "psm", topic: "Trade secrets", q: "PSM information needed for PHA, procedures, and contractors:", choices: ["Must still be provided; confidentiality agreements can protect trade secrets without blocking safety information", "Can be withheld entirely from the PHA team", "Is banned", "Goes only to OSHA, never workers"], a: 0, why: "1910.119(p): trade secrets cannot prevent compliance." },
  { id: "ps-13", category: "psm", topic: "Emergency PSM", q: "PSM facilities must have an emergency action plan meeting 1910.38, and if they will respond to a release:", choices: ["HAZWOPER 1910.120(q) also applies", "No extra plan", "Only a Twitter account", "Evacuation is banned"], a: 0, why: "1910.119(n): emergency planning. Coordinate with local responders (LEPC)." },
  { id: "ps-14", category: "psm", topic: "Compliance audit", q: "PSM compliance audits are required at least every:", choices: ["3 years", "10 years", "6 months", "Never"], a: 0, why: "1910.119(o): at least one person knowledgeable in the process on the audit team. Retain the two most recent reports." },
  { id: "ps-15", category: "psm", topic: "Employee participation", q: "Employers must have a written plan for:", choices: ["Employee participation in PHA and other PSM elements", "Keeping operators out of safety meetings", "Fines only", "Optional suggestion boxes as the sole element"], a: 0, why: "1910.119(c): consult with employees and their representatives. Provide access to PHA and incident reports." },

  { id: "tl-01", category: "tools", topic: "Condition", q: "Hand and power tools must be:", choices: ["Maintained in a safe condition; damaged tools removed from service", "Used until they fail in someone’s hand", "Home-made from rebar always", "Ungrounded even if designed for a ground"], a: 0, why: "1926.300 / 1910.242: inspect. Mushroomed chisels and split handles cause injuries." },
  { id: "tl-02", category: "tools", topic: "Mushroomed", q: "A mushroomed head on a chisel or hammer:", choices: ["Can chip and strike the eyes; dress the head or replace the tool", "Is a sign of quality", "Improves striking", "Needs no eye protection"], a: 0, why: "1926.301: keep impact tools free of mushroomed heads. Wear eye protection." },
  { id: "tl-03", category: "tools", topic: "Circular saw", q: "A portable circular saw must have:", choices: ["An upper guard and a lower retracting guard that returns to cover the blade", "No guards for plunge cuts as a habit", "A blade with missing teeth for speed", "The cord cut short"], a: 0, why: "1926.304 / 1910.243: guards. Do not wedge the lower guard open." },
  { id: "tl-04", category: "tools", topic: "Pneumatic", q: "Pneumatic hoses must be:", choices: ["Secured to prevent them from being accidentally disconnected and whipping", "Used as jump ropes", "Held by a coworker at the fitting during use", "Rated below the compressor pressure"], a: 0, why: "1926.302(b): safety clips/retainers on connections. Whip checks on larger hoses." },
  { id: "tl-05", category: "tools", topic: "Air used to clean", q: "Compressed air used for cleaning shall not exceed:", choices: ["30 psi, and then only with effective chip guarding and PPE", "90 psi always", "200 psi", "No limit"], a: 0, why: "1910.242(b): 30 psi for cleaning. Never use compressed air to blow clothing on the body — embolism hazard. Silica rules further restrict blowing dust." },
  { id: "tl-06", category: "tools", topic: "Powder loads", q: "Powder-actuated tools:", choices: ["Must not be loaded until just before firing; unused tools left unloaded; never pointed at anyone", "Can be left loaded in a gang box", "Are toys", "Do not need hearing protection"], a: 0, why: "1926.302(e): trained operators, different loads for different materials, and a misfire procedure (wait, then carefully remove)." },
  { id: "tl-07", category: "tools", topic: "Jacks", q: "Jacks must be:", choices: ["Rated for the load, set on a firm foundation, and cribbed as required; do not exceed rated capacity", "Stacked on each other casually", "Used as a permanent support always without blocking", "Kicked out from under a load"], a: 0, why: "1926.305 / 1910.244: block the load. Hydraulic jacks can slowly settle." },
  { id: "tl-08", category: "tools", topic: "Abrasive wheel portable", q: "Portable grinders need:", choices: ["Guards positioned to deflect fragments; wheels matched to RPM and type (depressed center vs cutoff)", "Guards removed for a better angle always", "Wheels of unknown RPM", "Side grinding on a cutoff wheel not designed for it"], a: 0, why: "1910.243 / 1926.303: guards. Cutoff wheels are not for side grinding." },
  { id: "tl-09", category: "tools", topic: "GFCI tools", q: "Corded tools on construction sites generally need:", choices: ["GFCI protection on the circuit", "Two-prong cheater plugs", "Daisy-chained household power strips as the service", "No inspection"], a: 0, why: "1926.404(b). Inspect cords daily. Strain relief at plugs." },
  { id: "tl-10", category: "tools", topic: "Fuel tools", q: "Fuel-powered tools indoors:", choices: ["Create CO and fire hazards; ventilate and shut off to refuel after cooling as required", "Are safer than electric", "Can be refueled while running", "Need no fire extinguisher nearby"], a: 0, why: "1926.302(c): stop engines to refuel; no smoking. CO kills in basements and trailers." },
  { id: "tl-11", category: "tools", topic: "Powder misfire", q: "After a powder-actuated misfire, the operator should:", choices: ["Follow the manufacturer — typically keep the tool in firing position for a specified time, then unload carefully", "Look down the barrel", "Hit it with a hammer", "Hand it loaded to a helper"], a: 0, why: "1926.302(e)(6): wait at least 30 seconds in some procedures (check the tool manual). Treat it as live." },
  { id: "tl-12", category: "tools", topic: "Hydraulic", q: "Hydraulic jacks and tools can:", choices: ["Inject fluid under skin (injection injury) — a medical emergency even from a pinhole leak", "Only cause slips", "Never fail", "Be checked by running a hand along hoses under pressure"], a: 0, why: "Use cardboard to find leaks, not skin. Injection injuries look small and destroy tissue." },

  { id: "sw-01", category: "stairways", topic: "Subpart X", q: "Construction stairways and ladders are in:", choices: ["1926 Subpart X", "1926 Subpart P", "1910.120", "1926 Subpart CC"], a: 0, why: "1926.1050–1060. General industry stairs are 1910.25–26." },
  { id: "sw-02", category: "stairways", topic: "When required", q: "A stairway or ladder is required at access points that have a break in elevation of:", choices: ["19 inches or more", "4 feet only", "10 feet only", "30 inches only always"], a: 0, why: "1926.1051(a): 19 inches. Ramps are another option." },
  { id: "sw-03", category: "stairways", topic: "Pan stairs", q: "Stair pans that will be filled with concrete must be:", choices: ["Filled to the top of the pan, or fitted with temporary wood or other material until filled, except during construction of the stair", "Left as open pans for workers to climb on the rebar", "Covered with visqueen only", "Used only by ironworkers without fill"], a: 0, why: "1926.1052(b)(2): do not use skeleton metal stairs without pan fill or equivalent." },
  { id: "sw-04", category: "stairways", topic: "Landings", q: "Stairways must have landings at least:", choices: ["30 inches in the direction of travel and 22 inches wide, at every 12 feet of vertical rise or less", "12 inches square", "No landings ever", "Only at the top"], a: 0, why: "1926.1052(a)(1) and (a)(4): landing size and vertical rise limits." },
  { id: "sw-05", category: "stairways", topic: "Variation", q: "Riser height and tread depth on a stairway must not vary more than:", choices: ["1/4 inch in any stairway system", "2 inches", "1 inch", "No limit"], a: 0, why: "1926.1052(a)(3): 1/4-inch maximum variation. Uneven stairs cause falls." },
  { id: "sw-06", category: "stairways", topic: "Railings stairs", q: "Stairways with four or more risers or rising more than 30 inches need:", choices: ["At least one handrail and a stair rail system along each unprotected side or edge", "No rails during construction", "Caution tape", "A rope at 60 inches"], a: 0, why: "1926.1052(c): height of stair rails 36–37 inches (as specified for mid-2010s vs older), handrails 30–37 inches. Know the current text for your installation date." },
  { id: "sw-07", category: "stairways", topic: "Temporary stairs", q: "Temporary stairs must be:", choices: ["At least 22 inches wide, with specified angles, and not a collection of boxes", "Made of stacked pallets", "Steeper than 70 degrees", "Unlit"], a: 0, why: "1926.1052(a)(2): 22-inch minimum width. 30–50 degree angle range for standard stairs in GI; construction has similar safe-angle practice." },
  { id: "sw-08", category: "stairways", topic: "Spiral", q: "Spiral stairs in construction:", choices: ["Are generally allowed only for special limited access (tanks, towers) where a conventional stair is not practical, with extra rules", "Are preferred for all buildings", "Need no handrails", "Can be unlit rebar coils"], a: 0, why: "1926.1052(a)(5): limited use of spiral stairs." },
  { id: "sw-09", category: "stairways", topic: "Slippery stairs", q: "Stair treads must be:", choices: ["Reasonably slip-resistant and kept clear of ice, mud, and debris", "Greased for form release as a walking surface", "Used to store lumber", "Open-riser always without consideration"], a: 0, why: "Housekeeping plus the stair standard. Ice on metal pans is a classic fall." },
  { id: "sw-10", category: "stairways", topic: "Ladder vs stair", q: "When a stair would be used by many workers with tools, the better choice is usually:", choices: ["A properly built stair or stair tower rather than a single portable ladder", "A rope", "Jumping", "A pile of dirt"], a: 0, why: "Ladders are for limited access. Scaffold stair towers exist for a reason." },

  { id: "gi-01", category: "intro", topic: "OSH Act 5(a)(2)", q: "Section 5(a)(2) of the OSH Act requires employers to:", choices: ["Comply with occupational safety and health standards promulgated under the Act", "Pay OSHA inspectors", "Provide company cars", "Offer stock options"], a: 0, why: "5(a)(1) is general duty; 5(a)(2) is comply with the standards. Workers have 5(b) duties too." },
  { id: "gi-02", category: "intro", topic: "Employee duty", q: "Section 5(b) requires each employee to:", choices: ["Comply with OSHA standards and rules applicable to their own actions and conduct", "Inspect the entire plant alone", "Pay for all PPE", "Never report hazards"], a: 0, why: "Workers must follow the rules. That does not shift the employer’s primary responsibility." },
  { id: "gi-03", category: "intro", topic: "NIOSH", q: "NIOSH is:", choices: ["A research agency (CDC) that develops recommended exposure limits and investigates hazards; it does not issue OSHA citations", "The enforcement branch of OSHA", "A state plan", "A union"], a: 0, why: "NIOSH RELs vs OSHA PELs. Health Hazard Evaluations (HHEs) are NIOSH tools." },
  { id: "gi-04", category: "intro", topic: "BLS", q: "National workplace injury statistics are published by:", choices: ["The Bureau of Labor Statistics (SOII), using OSHA log data and surveys", "FEMA only", "The Census of only fatal construction falls", "Wikipedia"], a: 0, why: "BLS SOII and CFOI. OSHA uses the data for targeting." },
  { id: "gi-05", category: "intro", topic: "VPP", q: "OSHA’s Voluntary Protection Programs (VPP):", choices: ["Recognize worksites with outstanding safety and health systems; they are not a substitute for compliance", "Exempt employers from all standards", "Are required for OSHA 30", "Replace workers’ comp"], a: 0, why: "Star and Merit sites still must follow the law. Inspections are different but not zero." },
  { id: "gi-06", category: "intro", topic: "National Emphasis", q: "A National Emphasis Program (NEP) means OSHA will:", choices: ["Target inspections at a defined hazard (e.g., heat, silica, trenching, warehouses)", "Stop all other inspections", "Only write letters", "Ban the industry"], a: 0, why: "NEPs drive programmed inspections. Trenching NEP is well known in construction." },
  { id: "gi-07", category: "intro", topic: "Imminent danger", q: "If an inspector finds imminent danger, they will:", choices: ["Ask the employer to immediately abate and remove workers; they can seek a court order if the employer refuses", "Come back next year", "Only issue a pamphlet", "Arrest the worker"], a: 0, why: "The inspector does not personally shut the job like a police officer in most cases, but the legal tools are fast. Workers should leave the danger." },
  { id: "gi-08", category: "intro", topic: "Closing conference", q: "At the closing conference, OSHA discusses:", choices: ["Apparent violations, abatement, and employer/employee rights", "The inspector’s vacation", "Only good news", "Union elections"], a: 0, why: "Citations come later in writing. You can ask questions and provide extra documents." },
  { id: "gi-09", category: "intro", topic: "Informal conference", q: "After a citation, an employer may request an informal conference:", choices: ["Usually within the 15-working-day contest period, to discuss penalties and abatement with the area director", "Only after 90 days", "Never", "Only in federal court first"], a: 0, why: "Informal conferences can lead to settlements. Contesting is a separate legal path to the Review Commission." },
  { id: "gi-10", category: "intro", topic: "OSHRC", q: "Contested citations are heard by:", choices: ["The Occupational Safety and Health Review Commission, an independent agency", "NIOSH", "The same OSHA inspector as judge", "The local building department"], a: 0, why: "OSHRC ALJs hear cases. Appeals can go to the Commission and then federal courts." },

  { id: "fp-37", category: "fallProtection", topic: "Hole size", q: "In construction, a hole is a gap or void 2 inches or more in its least dimension in a floor, roof, or other walking surface. Fall protection for holes is required at:", choices: ["6 feet or more to the lower level (and falling-object protection as specified)", "Only at 15 feet", "Never if 2 inches", "Only for 12-inch holes"], a: 0, why: "1926.500 definitions and 1926.501(b)(4). Small holes still trip and drop tools. Larger holes swallow people." },
  { id: "fp-38", category: "fallProtection", topic: "Excavation fall", q: "Walkways over excavations generally need guardrails when the walkway is:", choices: ["6 feet or more above the lower level", "2 feet above", "Always exempt", "Only at 20 feet"], a: 0, why: "1926.501(b)(7) and 1926.651(l): walkways over excavations. Also keep spoils back." },
  { id: "fp-39", category: "fallProtection", topic: "Formwork", q: "Employees on formwork and reinforcing steel generally need fall protection at:", choices: ["6 feet", "15 feet always like steel erection", "30 feet", "Never"], a: 0, why: "1926.501(b)(5): formwork and reinforcing steel at 6 feet. Positioning systems are common on rebar walls with PFAS as required." },
  { id: "fp-40", category: "fallProtection", topic: "Residential roofing steep", q: "Roofers on a steep roof need:", choices: ["Conventional fall protection (guardrails, nets, or PFAS) — not a warning line system", "Only slide guards as the sole OSHA system after 2017 residential changes", "No protection under 25 feet", "A monitor 100 feet away as the only system"], a: 0, why: "Warning lines are for low-slope. Steep roofs: conventional systems. Safety monitors have tight limits on low-slope with warning lines." },
  { id: "fp-41", category: "fallProtection", topic: "Monitor", q: "A safety monitor used with a warning-line system must be:", choices: ["A competent person on the same roof, within sight and voice, with no other duties that take attention from the monitor role", "Anyone on the ground with a phone", "A laborer hanging trusses at the same time", "Optional if you have caution tape"], a: 0, why: "1926.502(h): monitor duties. Only used on low-slope roofs as part of the specified systems." },
  { id: "fp-42", category: "fallProtection", topic: "Covers traffic", q: "Covers on holes in roadways or that support vehicles must be:", choices: ["Capable of supporting 2 times the maximum axle load of the largest vehicle expected", "Plywood of any thickness", "Snow fence", "Caution tape"], a: 0, why: "1926.502(i)(3)–(4): 2× pedestrian load for employee covers; 2× axle load for vehicle covers." },
  { id: "fp-43", category: "fallProtection", topic: "Top rail scaffold", q: "Scaffold guardrail height when PFAS is not used is generally:", choices: ["38 to 45 inches for supported scaffolds manufactured/used under current rules (check 1926.451(g)(4) for the installation date split)", "21 inches", "60 inches", "12 inches"], a: 0, why: "1926.451(g)(4): 38–45 inches for scaffolds manufactured after Jan 1, 2000 in many cases; older 36–45. Know your frames." },
  { id: "fp-44", category: "fallProtection", topic: "Cross-bracing as rail", q: "Cross-bracing on a scaffold may count as a midrail or top rail only when:", choices: ["The crossing point is at the required height range for that member", "Always, at any height", "Never", "Only if painted"], a: 0, why: "1926.451(g)(4)(xv): the crossing point must be 20–30 inches for a midrail equivalent, or 38–48 inches for a toprail equivalent, and the end frames still need a rail on the other side as specified." },
  { id: "fp-45", category: "fallProtection", topic: "Pump jack", q: "Pump-jack scaffolds have:", choices: ["Specific 1926.452(j) rules including workbench as a toprail in some setups and fall protection at 10 feet", "No fall protection ever", "The same as a boom lift", "Unlimited height without ties"], a: 0, why: "Poles must be secured. Fall protection still applies. Do not overload workbenches." },

  { id: "ex-23", category: "excavation", topic: "Benchtop", q: "Benching is not an option in:", choices: ["Type C soil (Appendix B does not allow benching in Type C)", "Type A", "Type B in some tabulated data", "Stable rock"], a: 0, why: "Type C can only be sloped (or supported/shielded), not benched, under OSHA’s tabulated data." },
  { id: "ex-24", category: "excavation", topic: "Layered", q: "In layered soils, you generally classify and slope for:", choices: ["The weakest (least stable) layer that affects the excavation", "Only the top inch", "Type A if any clay is present", "Whatever is fastest"], a: 0, why: "A weak layer under a crust is a classic collapse setup. Classify conservatively." },
  { id: "ex-25", category: "excavation", topic: "Fissured", q: "Fissured soil cannot be:", choices: ["Type A", "Type C", "Shielded", "Sloped"], a: 0, why: "Appendix A: fissured, previously disturbed, or subject to vibration — not Type A." },
  { id: "ex-26", category: "excavation", topic: "Thumb test", q: "The thumb penetration test is a:", choices: ["Field method to help estimate unconfined compressive strength of cohesive soil", "Legal substitute for a PE at 25 feet", "Test for sand only", "Required daily by name in every trench"], a: 0, why: "Appendix A: pocket penetrometer, shear vane, and thumb test. Plasticity and drying tests too. Document the classification." },
  { id: "ex-27", category: "excavation", topic: "Stable rock", q: "Stable rock is:", choices: ["Natural solid mineral that can be excavated with vertical sides and remain intact while exposed", "Hard clay", "Compacted fill", "Asphalt millings"], a: 0, why: "Few jobsites have true stable rock. When in doubt, protect." },
  { id: "ex-28", category: "excavation", topic: "Tabulated data", q: "Manufacturers’ tabulated data for shields must be:", choices: ["On site and followed, including depth ratings and soil types", "Left at the yard", "Optional if the box looks strong", "Used past the rating if you work fast"], a: 0, why: "1926.652(c)(2): tabulated data. A PE designs when you go outside the data." },
  { id: "ex-29", category: "excavation", topic: "Ramp structural", q: "Earthen ramps used for access must be:", choices: ["Uniform and have a surface that workers will not slip on; structural ramps for equipment need PE design", "Cut at 60 degrees", "Used as spoil storage", "Only one boot-width wide"], a: 0, why: "1926.651(c): distinguish employee ramps vs vehicle ramps." },
  { id: "ex-30", category: "excavation", topic: "Crossing", q: "Walkways over trenches must be:", choices: ["Equipped with guardrails if 6 feet or more above the lower level", "A single 2x10 with no rails at 10 feet", "Optional if workers jump", "Made of caution tape"], a: 0, why: "1926.651(l): walkways and bridges. Guardrails per Subpart M." },

  { id: "el-26", category: "electrical", topic: "GFCI monthly", q: "GFCI devices should be:", choices: ["Tested (test/reset) as the manufacturer specifies — often before use or monthly", "Never tested so they last longer", "Bypassed with a cheater", "Used as the lockout device"], a: 0, why: "A GFCI that does not trip is a false sense of security. Portable GFCIs get abused on sites." },
  { id: "el-27", category: "electrical", topic: "Assured colors", q: "AEGCP quarterly tests are often identified by:", choices: ["A color-coded tape system by quarter (example: white, green, red, orange — follow the written program)", "Painting the whole cord", "No marking", "A knot in the cord"], a: 0, why: "1926.404(b)(1)(iii): marking to indicate the most recent test. Programs vary by color — know yours." },
  { id: "el-28", category: "electrical", topic: "Wet concrete pump", q: "A concrete pump placing boom near power lines is:", choices: ["An electrocution hazard like a crane — maintain clearance or de-energize", "Safe because concrete is a ground", "Exempt from 10-foot rules", "Only a struck-by hazard"], a: 0, why: "Booms conduct. Spotters and dedicated observers save lives." },
  { id: "el-29", category: "electrical", topic: "Underground 811", q: "Before excavation, calling 811:", choices: ["Starts the locate process for many utilities; wait the required time and respect marks", "Replaces a private locate for site-owned lines always", "Is optional if you “know the site”", "Means you can use a backhoe on the marks"], a: 0, why: "Hand-dig in the tolerance zone. Private lines (site lighting, fire loops) may need a private locator." },
  { id: "el-30", category: "electrical", topic: "Temp panel", q: "Temporary power panels on construction sites must have:", choices: ["Covers, proper breakers, strain relief, and GFCI where required; not open live parts", "Bare bus bars for easy access", "Household extension-cord “pig tails” as the service", "No identification of circuits"], a: 0, why: "1926.404–405: cabinets, fittings, and wet-location extra-hard-usage cords." },

  { id: "hh-27", category: "health", topic: "Silica medical", q: "Medical surveillance for silica is generally required when:", choices: ["The worker will be exposed at or above the action level for 30 or more days a year", "They cut concrete once", "They wear a hat", "Never in construction"], a: 0, why: "1926.1153(h): medical every 3 years (or as the PLHCP recommends) including TB screening and lung evaluation." },
  { id: "hh-28", category: "health", topic: "Beryllium", q: "Beryllium (1910.1024 / 1926.1124) is a concern in:", choices: ["Certain metals, aerospace, and some ceramics — it can cause chronic beryllium disease", "Softwood dust only", "Office paper", "Water"], a: 0, why: "Very low PELs. Grinding beryllium-copper needs strict controls." },
  { id: "hh-29", category: "health", topic: "Cadmium", q: "Cadmium fume from welding or brazing on plated steel is:", choices: ["Highly toxic to kidneys and lungs; use ventilation and the cadmium standard when it applies", "A vitamin", "Only a fire hazard", "Harmless if you cannot smell it"], a: 0, why: "1910.1027. “Silver solder” and coatings can contain cadmium. Do not weld in a closed room." },
  { id: "hh-30", category: "health", topic: "Mold", q: "OSHA does not have a mold PEL, but:", choices: ["The General Duty Clause and sanitation/ventilation rules can still apply; fix moisture and protect workers during remediation", "Mold is never an OSHA issue", "Bleach without PPE is always required", "Only EPA cites mold"], a: 0, why: "Water-damaged buildings: PPE, containment, and competent remediation. Asthmatics are at higher risk." },
  { id: "hh-31", category: "health", topic: "Nanomaterials", q: "Engineered nanomaterials should be:", choices: ["Treated with caution — use containment, HEPA, and avoid dry sweeping; follow NIOSH and SDS", "Handled like sand without controls", "Eaten to test toxicity", "Blown with compressed air"], a: 0, why: "Emerging hazard. Carbon nanotubes have NIOSH RELs. Do not improvise." },
  { id: "hh-32", category: "health", topic: "Diesel PM", q: "Diesel exhaust in tunnels, shops, and warehouses:", choices: ["Contains particulates and gases; ventilate, restrict idling, and consider after-treatment", "Is healthy", "Only smells bad", "Is unregulated in every sense"], a: 0, why: "MSHA has DPM rules in mines. OSHA uses PELs for components (NO2, CO, etc.) and General Duty for the mix. Cancer hazard." },

  { id: "pp-28", category: "ppe", topic: "FR clothing", q: "Flame-resistant clothing is required when:", choices: ["The employer’s assessment (or a standard such as 1910.269 / 1926.960 for electrical, or welding/molten metal) identifies a flash-fire or arc hazard that FR will mitigate", "You work outdoors in winter only", "Always for OSHA 10 graduates", "Never in general industry"], a: 0, why: "NFPA 70E and 2112 are consensus standards OSHA often looks to. Cotton vs polyester: synthetics melt." },
  { id: "pp-29", category: "ppe", topic: "Arc rating", q: "An ATPV or EBT on FR clothing is:", choices: ["The arc rating in cal/cm² used to select clothing for the incident energy", "A fashion size", "The hard-hat class", "The noise NRR"], a: 0, why: "Match clothing to the arc-flash study. A 4 cal shirt is not enough for a 25 cal task." },
  { id: "pp-30", category: "ppe", topic: "Life vests", q: "When working over or near water where a drowning hazard exists, construction rules require:", choices: ["U.S. Coast Guard-approved life jackets/vests, ring buoys, and a skiff as specified in 1926.106", "Only a hard hat", "Swim lessons as the only control", "No flotation if you can swim"], a: 0, why: "1926.106: PFDs, 90 feet of line on buoys at 200-foot intervals, and a boat where the water is too dangerous for buoys alone." },

  { id: "lo-23", category: "loto", topic: "Group box", q: "A lockbox group lockout typically works by:", choices: ["Each worker’s lock on the box that holds the keys to the equipment locks, so energy cannot be restored until the last personal lock is removed", "One shared key under a mat", "Tags without locks always", "The supervisor keeping all personal keys"], a: 0, why: "The equipment remains isolated. Personal locks on the box equal personal protection." },
  { id: "lo-24", category: "loto", topic: "Complex", q: "Complex LOTO (many isolation points) often uses:", choices: ["A written procedure, a principal authorized employee, and verification that every point is isolated", "Memory only", "A single breaker for an entire plant always", "No tags"], a: 0, why: "1910.147(f)(4) note / OSHA directive: group lockout of complex systems. Verify. Blind flanges and valves count." },
  { id: "lo-25", category: "loto", topic: "Line breaking", q: "Opening a process line (line breaking) is:", choices: ["Servicing that generally requires isolation, LOTO, and residual-chemical controls — not “just a wrench job”", "Exempt from LOTO always", "Only a HazCom issue", "Safe if the valve is painted"], a: 0, why: "Hot condensate, chemicals, and stored pressure kill. Drain, purge, and verify." },

  { id: "hc-23", category: "hazcom", topic: "HCS 2024", q: "OSHA’s Hazard Communication updates aligned with later GHS revisions. Employers must:", choices: ["Keep labels and SDS current and train employees on any new label/SDS format elements that apply to their chemicals", "Ignore updates if they trained in 2013", "Stop using pictograms", "Remove Section 16"], a: 0, why: "Stay current with 1910.1200 amendments. Distributors and manufacturers have phased effective dates. Training is still the employer’s duty." },
  { id: "hc-24", category: "hazcom", topic: "Small container", q: "Very small shipped containers may use:", choices: ["Specified reduced labeling in some cases, but workers still need access to full hazard information", "No information", "Only a SKU", "A handwritten skull"], a: 0, why: "1910.1200(f) has provisions for small packages. Workplace labels still must communicate hazards." },
  { id: "hc-25", category: "hazcom", topic: "Distributor", q: "A distributor who ships hazardous chemicals must:", choices: ["Ensure containers are labeled and SDS are provided downstream", "Remove labels to look neat", "Ship without SDS if the customer “already knows”", "Use only Spanish labels in every state"], a: 0, why: "Manufacturers, importers, and distributors have 1910.1200(g) SDS duties. Employers who use chemicals have workplace duties." },

  { id: "ff-18", category: "focusFour", topic: "Stats", q: "OSHA and BLS data show construction’s leading fatal event is typically:", choices: ["Falls to a lower level", "Office repetitive motion", "Bee stings", "Paper cuts"], a: 0, why: "Focus Four exists because the data is consistent year after year. Control falls first." },
  { id: "ff-19", category: "focusFour", topic: "Vehicle backup", q: "Dump trucks and loaders backing on a site are a:", choices: ["Struck-by hazard — backup alarms, cameras, spotters, and exclusion zones", "Fall hazard only", "Only a noise issue", "Caught-in trench only"], a: 0, why: "1926.601–602 and work-zone practices. Blind spots are huge. Spotters must be visible to the driver." },
  { id: "ff-20", category: "focusFour", topic: "Trench plus fall", q: "An unprotected trench that is also a walkway hazard can be:", choices: ["Both a cave-in (caught-in) and a fall hazard", "Neither", "Only electrical", "Only health"], a: 0, why: "Workers fall into trenches and get buried. Guard or cover, and use protective systems." }
];
